/**
 * Workbooks that Excel did NOT write (round 5, module H1). The corpus (tests/fixtures/foreign/corpus, regenerated by
 * tests/fixtures/foreign/make-corpus.py / make-corpus.mjs) holds Google Sheets / LibreOffice / Apache POI / Open XML SDK / Mac Excel
 * 2011 / Excel 2007 / ERP-converter / Strict OOXML / openpyxl / XlsxWriter / pandas / ExcelJS / SheetJS / xlsx-populate packages.
 *
 *  1. every file goes through readBook -> keys -> buildPremerged -> doc ops -> replayLog in both roles (base / other) and both join types
 *     with the invariants of tests/fixtures/foreign/harness.ts (premerge keeps the base, imports arrive with text + style + width, doc ==
 *     readBook(replayLog), charts follow their columns, notes agree with their VML, no exception but a clean Japanese refusal);
 *  2. one regression test per bug found in this round (each names its corpus file).
 */
import fs from 'node:fs';
import path from 'node:path';
import JSZip from 'jszip';
import { describe, expect, it } from 'vitest';
import { createEditor, setCellInput } from '../../src/core/doc';
import { defaultColumnPx, mdwFor, pxToExcelWidth } from '../../src/core/display/styles';
import { cellText, readBook, replayLog } from '../../src/core/xlsx';
import { unesc } from '../../src/core/xlsx/patch/xml';
import { decodeXmlText } from '../../src/core/xlsx/xml';
import type { LoggedOp, SourceBook } from '../../src/core/types';
import { CORPUS_DIR, PARTNER, bookDiff, load, loadBytes, premergeFiles, runPipeline } from '../fixtures/foreign/harness';

const files = fs.readdirSync(CORPUS_DIR).filter((f) => /\.(xlsx|xlsm)$/i.test(f) && f !== PARTNER).sort();
const bytesOf = (name: string) => new Uint8Array(fs.readFileSync(path.join(CORPUS_DIR, name)));
const L = (name: string) => load(CORPUS_DIR, name, 'x');
const partner = () => L(PARTNER);
const zipOf = (b: Uint8Array) => JSZip.loadAsync(b);
const text = async (b: Uint8Array, p: string) => (await (await zipOf(b)).file(p)?.async('string')) ?? null;
const names = async (b: Uint8Array) => Object.keys((await zipOf(b)).files).filter((n) => !n.endsWith('/'));
const sheetOf = (b: SourceBook, name?: string) => b.sheets.find((s) => s.name === name) ?? b.sheets[0];

/** files the app cannot merge (clean Japanese refusal) in a given role: the insert would push data off the sheet edge (XFD) */
const REFUSED: Record<string, string[]> = { 'py-26-openpyxl-xfd-columns.xlsx': ['base'] };

/**
 * Round 8: XlsxWriter writes 0 as the "result" of every formula (and asks Excel to recalculate on load). Those zeros are placeholders, not
 * results, so the premerge does not copy them: a formula that stays live gets no stored result (Excel computes it), and the
 * 'formulasPlaceholderCache' warning says so. The harness compares the displayed text of every imported cell with the source: for these files
 * the only accepted difference is "0" -> "" on a formula cell.
 */
const PLACEHOLDER_RESULTS = new Set(['py-19-xlsxwriter-table.xlsx']);
const ZERO_TO_EMPTY = /: "0" -> ""$/;

describe('corpus of workbooks from other producers', () => {
  it('has the files it claims to have', () => {
    expect(files.length).toBeGreaterThanOrEqual(60);
    for (const prefix of ['hc-01-google', 'hc-02-libreoffice', 'hc-03-poi', 'hc-04-openxmlsdk', 'hc-05-mac', 'hc-06-excel2007', 'hc-08-strict', 'js-04-exceljs', 'js-01-sheetjs', 'js-08-xlsx-populate', 'py-01-openpyxl', 'py-15-xlsxwriter', 'py-20-pandas'])
      expect(files.some((f) => f.startsWith(prefix)), prefix).toBe(true);
  });

  for (const f of files) {
    it(`${f}: read -> region -> join -> premerge -> ops -> replay hold the invariants (both roles, left / full join)`, async () => {
      const file = await L(f);
      const p = await partner();
      const failures: string[] = [];
      for (const role of ['base', 'other'] as const) {
        for (const join of ['left', 'full'] as const) {
          // hc-24 uses Japanese part names that Excel itself cannot open; everything else is an Excel-valid file
          const r = await runPipeline(file, p, { role, join, seed: 1, steps: 10 });
          const expectedRefusal = REFUSED[f]?.includes(role);
          if (r.verdict === 'refused' && expectedRefusal) {
            expect(r.refusal).toMatch(/[぀-ヿ一-鿿]/);
            continue;
          }
          if (r.verdict === 'bug' && PLACEHOLDER_RESULTS.has(f) && r.problems.length > 0 && r.problems.every((x) => ZERO_TO_EMPTY.test(x))) continue;
          if (r.verdict !== 'ok') failures.push(`[${role}/${join}] ${r.verdict} at ${r.stage}: ${r.refusal ?? r.problems.join(' | ')} (ops: ${(r.info.trail ?? []).join('; ')})`);
        }
      }
      expect(failures).toEqual([]);
    });
  }
});

describe('package level: zip names, part names, namespace prefixes', () => {
  it('hc-12: entry names written with backslashes (old .NET ZipFile / PowerShell Compress-Archive) are read, and written back with "/"', async () => {
    const raw = await names(bytesOf('hc-12-zip-backslash-stored.xlsx'));
    expect(raw.some((n) => n.includes('\\'))).toBe(true); // the fixture really has them
    const book = await readBook(bytesOf('hc-12-zip-backslash-stored.xlsx'), 'hc-12.xlsx');
    expect(sheetOf(book).maxRow).toBeGreaterThan(30);
    const pm = await premergeFiles(await L('hc-12-zip-backslash-stored.xlsx'), await partner());
    const out = await names(pm.bytes);
    expect(out.some((n) => n.includes('\\'))).toBe(false);
    expect(out).toContain('xl/worksheets/sheet1.xml');
    expect(await text(await replayLog(pm.bytes, []), 'xl/workbook.xml')).toContain('名簿');
  });

  it('hc-23: part names that differ in case from the relationships / content types are found and overwritten in place (no second part)', async () => {
    const entries = await names(bytesOf('hc-23-part-name-case.xlsx'));
    expect(entries).toContain('XL/Worksheets/Sheet1.xml');
    const pm = await premergeFiles(await L('hc-23-part-name-case.xlsx'), await partner());
    const out = await names(pm.bytes);
    const sheets = out.filter((n) => /worksheets\/sheet1\.xml$/i.test(n));
    expect(sheets).toEqual(['XL/Worksheets/Sheet1.xml']);
    expect(out.filter((n) => /sharedstrings\.xml$/i.test(n))).toHaveLength(1);
    // the imported header reached the sheet that Excel will read
    expect(cellText(pm.book, sheetOf(pm.book, '名簿').rows[0]?.[7])).toBe('面接評価');
  });

  it('hc-13: a relationships namespace with another prefix (rel:id) is understood by the patcher', async () => {
    const f = await L('hc-13-odd-rel-prefix.xlsx');
    const pm = await premergeFiles(f, await partner());
    expect(sheetOf(pm.book).maxCol).toBeGreaterThan(7);
    const moved = await replayLog(pm.bytes, [{ kind: 'struct', sheet: '名簿', op: { type: 'move', axis: 'col', from: 1, count: 1, to: 5 } }]);
    expect(cellText(await readBook(moved, 'x.xlsx'), sheetOf(await readBook(moved, 'x.xlsx')).rows[0]?.[0])).toBe('氏名');
  });

  it('hc-24: Japanese part names (percent-encoded relationship target, raw entry name) are found', async () => {
    const pm = await premergeFiles(await L('hc-24-japanese-part-names.xlsx'), await partner());
    expect(sheetOf(pm.book).maxCol).toBeGreaterThan(7);
  });
});

describe('date systems (1904 books: Mac Excel 2011, openpyxl epoch, SheetJS WBProps)', () => {
  const ser2026 = 46315; // 2026/10/20 in the 1900 system (what the doc holds)

  for (const name of ['py-06-openpyxl-date1904.xlsx', 'hc-05-mac-excel-2011-1904.xlsx', 'js-02-sheetjs-date1904.xlsx']) {
    it(`${name}: a date typed into a 1904 book reads back as the same date (the file stores the 1904 serial)`, async () => {
      const f = await L(name);
      const pm = await premergeFiles(f, await partner());
      const s0 = createEditor(pm.book, pm.layout, { s1: { label: 'a', color: '#000' }, s2: { label: 'b', color: '#111' } }, { headerRow: f.ks.region.headerRow, firstDataRow: f.ks.region.firstDataRow, lastDataRow: f.ks.region.lastDataRow });
      expect(pm.book.date1904).toBe(true);
      const dateCol = s0.doc.columns.findIndex((c) => c.id === 'b6'); // 入学日
      const res = setCellInput(s0, s0.doc.columns[dateCol].id, f.ks.region.firstDataRow, '2026/10/20');
      if (!res.ok) throw new Error(res.reason);
      const out = await replayLog(pm.bytes, res.snapshot.log);
      const back = await readBook(out, name);
      const cell = sheetOf(back).rows[f.ks.region.firstDataRow - 1]?.[dateCol];
      expect(cell?.v).toBe(ser2026);
      expect(cellText(back, cell)).toBe('2026/10/20');
      // in the file the value is a 1904 serial: 46315 - 1462
      const xml = (await text(out, 'xl/worksheets/sheet1.xml'))!;
      expect(xml).toMatch(new RegExp(`<c r="${String.fromCharCode(65 + dateCol)}${f.ks.region.firstDataRow}"[^>]*><v>44853</v>`));
    });
  }

  it('hc-05 -> 1900 book: dates shift by 1462 days, a time of day and a [h]:mm duration keep their value', async () => {
    const p = await partner();
    const f = await L('hc-05-mac-excel-2011-1904.xlsx');
    const pm = await premergeFiles(p, f); // the Mac file is the OTHER book (1904 -> 1900)
    expect(pm.book.date1904).toBe(false);
    const src = sheetOf(f.book);
    const out = sheetOf(pm.book);
    const colOf = (head: string) => out.rows[0]!.findIndex((c) => c?.v === head);
    const sc = (head: string) => src.rows[0]!.findIndex((c) => c?.v === head);
    // matched rows: the partner's S2024003.. = Mac file rows 4..; compare a few
    let checked = 0;
    for (let r = 2; r <= 8; r++) {
      const id = out.rows[r - 1]?.[0]?.v;
      const srow = src.rows.findIndex((row) => row?.[0]?.v === id) + 1;
      if (!srow) continue;
      for (const head of ['始業', '所要', '受付日時', '入学日']) {
        const a = src.rows[srow - 1]![sc(head)]!;
        const b = out.rows[r - 1]![colOf(head) >= 0 ? colOf(head) : colOf(`${head}（${f.ks.label}）`)];
        expect(cellText(pm.book, b), `${head} row ${r}`).toBe(cellText(f.book, a));
        if (head === '所要') expect(b?.v).toBeCloseTo(a.v as number, 9); // the duration is not a date
        if (head === '始業') expect(b?.v).toBeLessThan(1);
        checked++;
      }
    }
    expect(checked).toBeGreaterThanOrEqual(20);
  });

  it('py-10 / hc-08: ISO dates (t="d" cells) are imported as date serials with a date format, not as text', async () => {
    for (const name of ['py-10-openpyxl-iso-dates.xlsx', 'hc-08-strict-ooxml.xlsx']) {
      const f = await L(name);
      const pm = await premergeFiles(await partner(), f);
      const g = sheetOf(pm.book);
      const col = g.rows[0]!.findIndex((c) => c?.v === '入学日');
      const cell = g.rows[1]?.[col];
      expect(cell?.t, name).toBe('d');
      expect(typeof cell?.v, name).toBe('number');
      expect(cellText(pm.book, cell), name).toMatch(/^2024\/\d{1,2}\/\d{1,2}$/);
    }
  });

  it('py-10: an ISO date imported into a 1904 base becomes that base\'s serial', async () => {
    const pm = await premergeFiles(await L('py-06-openpyxl-date1904.xlsx'), await L('py-10-openpyxl-iso-dates.xlsx'));
    expect(pm.book.date1904).toBe(true);
    const g = sheetOf(pm.book);
    const col = g.rows[0]!.findIndex((c) => typeof c?.v === 'string' && /^入学日/.test(c.v) && c.v !== '入学日');
    const src = sheetOf((await L('py-10-openpyxl-iso-dates.xlsx')).book);
    const id = g.rows[1]?.[0]?.v;
    const srow = src.rows.findIndex((row) => row?.[0]?.v === id);
    expect(col).toBeGreaterThan(7);
    expect(srow).toBeGreaterThan(0);
    expect(cellText(pm.book, g.rows[1]![col])).toBe(cellText((await L('py-10-openpyxl-iso-dates.xlsx')).book, src.rows[srow]![5]));
  });
});

describe('styles of packages without (or with unusual) style parts', () => {
  it('hc-09: a base without styles.xml keeps its cells bottom aligned like Excel shows them (no vertical centre added)', async () => {
    const pm = await premergeFiles(await L('hc-09-minimal-no-parts.xlsx'), await partner());
    const a = sheetOf(pm.book).rows[1]![0]!;
    expect(pm.book.styles[a.s ?? 0].vAlign).toBeUndefined();
    const before = sheetOf((await L('hc-09-minimal-no-parts.xlsx')).book).rows[1]![0]!;
    expect(pm.book.styles[a.s ?? 0]).toEqual((await L('hc-09-minimal-no-parts.xlsx')).book.styles[before.s ?? 0]);
  });

  it('hc-27: a custom indexed palette (<colors><indexedColors>) of the source does not change the colours of imported cells', async () => {
    const src = await L('hc-27-custom-indexed-palette.xlsx');
    expect(src.book.styles[sheetOf(src.book).rows[0]![0]!.s ?? 0]).toMatchObject({ fill: '#00AA00', color: '#AA0000' });
    const pm = await premergeFiles(await partner(), src);
    const g = sheetOf(pm.book);
    const col = g.rows[0]!.findIndex((c) => c?.v === '大学');
    const style = pm.book.styles[g.rows[0]![col]!.s ?? 0];
    expect(style.fill).toBe('#00AA00');
    expect(style.color).toBe('#AA0000');
    // the base's own (default palette) cells are untouched
    expect(pm.book.styles[g.rows[0]![0]!.s ?? 0].fill).not.toBe('#00AA00');
  });
});

describe('legacy notes, charts and drawings written by other producers', () => {
  const structOp = (op: LoggedOp & { kind: 'struct' }): LoggedOp[] => [op];

  it('py-11 (openpyxl: notes in VML with ns0: / ns1: / ns2: prefixes): a note follows its cell when the column moves', async () => {
    // B2 has the note; moving B to the far right must move the VML shape (x:Column) with it, or Excel drops the note
    const ops = structOp({ kind: 'struct', sheet: '名簿', op: { type: 'move', axis: 'col', from: 2, count: 1, to: 9 } });
    const out = await replayLog(bytesOf('py-11-openpyxl-chart-names-links.xlsx'), ops);
    const comments = (await text(out, 'xl/comments/comment1.xml'))!;
    const vml = (await text(out, 'xl/drawings/commentsDrawing1.vml'))!;
    expect(comments).toMatch(/<comment ref="H2"/);
    const col = /<(?:[\w.-]+:)?Column>\s*(\d+)/.exec(vml)![1];
    const row = /<(?:[\w.-]+:)?Row>\s*(\d+)/.exec(vml)![1];
    expect([Number(col), Number(row)]).toEqual([7, 1]); // H2, 0-based
  });

  it('py-11 / py-27 (openpyxl charts in the default namespace: <f>, not <c:f>): series formulas follow moved columns', async () => {
    const ops = structOp({ kind: 'struct', sheet: '名簿', op: { type: 'move', axis: 'col', from: 5, count: 1, to: 2 } }); // 点数 E -> B (inserted before B)
    const out = await replayLog(bytesOf('py-11-openpyxl-chart-names-links.xlsx'), ops);
    const chart = (await text(out, 'xl/charts/chart1.xml'))!;
    expect(chart).toContain("'名簿'!$B$2:$B$31"); // 点数 is now column B
    expect(chart).toContain("'名簿'!B1");
    expect(chart).not.toContain("'名簿'!$E$2:$E$31");
    //氏名 (was B) is now C
    expect(chart).toContain("'名簿'!$C$2:$C$31");
  });

  it('py-27 (openpyxl: a chart anchored on the data sheet in a default-namespace drawing): the anchor moves with an inserted column', async () => {
    const before = (await text(bytesOf('py-27-openpyxl-chart-on-data-sheet.xlsx'), 'xl/drawings/drawing1.xml'))!;
    expect(before).toMatch(/<oneCellAnchor><from><col>10<\/col>/); // K2
    const ops = structOp({ kind: 'struct', sheet: '名簿', op: { type: 'insert', axis: 'col', at: 3, count: 2 } });
    const out = await replayLog(bytesOf('py-27-openpyxl-chart-on-data-sheet.xlsx'), ops);
    const after = (await text(out, 'xl/drawings/drawing1.xml'))!;
    expect(after).toMatch(/<oneCellAnchor><from><col>12<\/col>/); // M2
    const chart = (await text(out, 'xl/charts/chart1.xml'))!;
    expect(chart).toContain("'名簿'!$G$2:$G$31"); // 点数 E -> G
    // the two notes (C3, G6 in VML with ns0: prefixes) moved too
    const comments = (await text(out, 'xl/comments/comment1.xml'))!;
    expect(comments).toMatch(/ref="E3"/);
    expect(comments).toMatch(/ref="I6"/);
  });

  it('py-15 (XlsxWriter notes: v: / x: prefixes, the prefixes Excel uses) still follow their cells', async () => {
    const out = await replayLog(bytesOf('py-15-xlsxwriter-basic.xlsx'), structOp({ kind: 'struct', sheet: '名簿', op: { type: 'insert', axis: 'col', at: 1, count: 1 } }));
    const comments = (await text(out, 'xl/comments1.xml'))!;
    expect(comments).toMatch(/ref="C4"/); // B4 -> C4
    expect(comments).toMatch(/ref="G8"/); // F8 -> G8
    const vml = (await text(out, 'xl/drawings/vmlDrawing1.vml'))!;
    expect([...vml.matchAll(/<x:Column>(\d+)<\/x:Column>/g)].map((m) => Number(m[1])).sort()).toEqual([2, 6]);
  });
});

describe('text content written with markup (CDATA, comments) and other lexical oddities', () => {
  it('decoders: CDATA sections are literal text, comments and processing instructions are not text', () => {
    expect(decodeXmlText('<![CDATA[a < b & c]]>')).toBe('a < b & c');
    expect(decodeXmlText('x<!-- gone -->y&amp;<![CDATA[&amp;]]>')).toBe('xy&&amp;');
    expect(decodeXmlText('plain &lt;b&gt;')).toBe('plain <b>');
    expect(unesc('<![CDATA[IF(A1<B1,1,0)]]>')).toBe('IF(A1<B1,1,0)');
    expect(unesc('a<?pi data?>b&quot;')).toBe('ab"');
    expect(unesc('no markup &amp; done')).toBe('no markup & done');
  });

  it('hc-26: IDs and memos written as <![CDATA[...]]> are read and imported as their text', async () => {
    const f = await L('hc-26-cdata-comments-entities.xlsx');
    const g = sheetOf(f.book);
    expect(g.rows[1]![0]!.v).toBe('S2024001');
    expect(g.rows[1]![2]!.v).toBe('a < b & c > d');
    expect(g.rows[5]![2]!.v).toBe('  padded  ');
    expect(g.rows[12]![2]!.v).toBe('ab'); // a comment inside <t> is not text
    const pm = await premergeFiles(await partner(), f);
    const m = sheetOf(pm.book);
    const col = m.rows[0]!.findIndex((c) => typeof c?.v === 'string' && c.v.startsWith('メモ（')); // the partner has its own メモ column
    const texts = m.rows.map((r) => r?.[col]?.v).filter((v) => typeof v === 'string');
    expect(texts).toContain('line1\nline2');
    expect(texts).toContain('<tag> & "q" \'a\'');
    expect(texts.some((t) => typeof t === 'string' && t.includes('CDATA'))).toBe(false);
  });
});

describe('formulas that cannot be kept when imported', () => {
  it('hc-34: a formula whose source stored no result (openpyxl) and cannot stay live is reported as EMPTY, not as "converted to a value"', async () => {
    const f = await L('hc-34-formulas-without-cache.xlsx');
    const pm = await premergeFiles(await partner(), f);
    const item = pm.report.items.find((i) => i.code === 'formulasNoCache');
    expect(item).toBeTruthy();
    expect(item!.message).toMatch(/計算結果が保存されていない/);
    // round 8: of the 84 result-less formulas 56 (RANK / share of the total over the table's own columns) stay live formulas now;
    // the 28 that read another sheet (INDEX(マスタ!…, MOD(ROW(),8)+1)) cannot and are the only EMPTY cells
    expect(item!.message).toMatch(/28 件/);
    expect(item!.message).toMatch(/Excelで開いて保存し直してください/);
    expect(item!.message).toMatch(/Excel で開いて保存し直して/);
    expect(pm.report.formulaStats).toEqual([{ sourceId: 's2', label: 'hc-34-formulas-without-cache', kept: 56, toValues: 0, empty: 28, reasons: { otherSheet: 28 } }]);
    expect(pm.report.items.some((i) => i.code === 'formulasToValues')).toBe(false); // nothing was converted to a value
  });

  it('py-19 (XlsxWriter): the 0 stored as every formula\'s result is no result — the table formulas stay live without one, and the user is told', async () => {
    const f = await L('py-19-xlsxwriter-table.xlsx');
    const pm = await premergeFiles(await partner(), f);
    // [[#This Row],点数]+10 : a structured reference without a table name (XlsxWriter) belongs to the table of the formula's cell
    expect(pm.report.formulaStats).toEqual([{ sourceId: 's2', label: 'py-19-xlsxwriter-table', kept: 28, toValues: 0, empty: 0, reasons: {} }]);
    expect(pm.report.items.find((i) => i.code === 'formulasPlaceholderCache')?.message).toMatch(/結果が 0 のまま保存されている/);
    expect(pm.report.items.some((i) => i.code === 'formulasNoCache')).toBe(false);
  });
});

describe('sheet format: baseColWidth (Mac Excel writes 10)', () => {
  it('hc-05: the reader reports the default column width derived from baseColWidth so the grid, the doc and the patcher agree', async () => {
    const b = await readBook(bytesOf('hc-05-mac-excel-2011-1904.xlsx'), 'x.xlsx');
    const g = sheetOf(b);
    const st = b.styles[0];
    const mdw = mdwFor(st.font, st.size ?? 11);
    expect(g.defaultColWidth).toBeCloseTo(pxToExcelWidth(defaultColumnPx(mdw, 10), mdw), 6);
    expect(g.defaultColWidth!).toBeGreaterThan(pxToExcelWidth(defaultColumnPx(mdw, 8), mdw));
  });
});

describe('hostile-ish but valid data from converters', () => {
  it('hc-22: lexical forms Excel itself rejects (+5, 0x10, NaN, 1,234, full-width digits) are read without failing and merge cleanly', async () => {
    const f = await L('hc-22-invalid-lexical-values.xlsx');
    expect(f.book.warnings.join('\n')).toMatch(/読み取れない値/);
    const r = await runPipeline(f, await partner(), { role: 'other', join: 'left', seed: 2, steps: 8 });
    expect(r.verdict).toBe('ok');
  });

  it('hc-18: valid but unusual numbers (1E2, .5, 5., 0012, " 7 ", -0, 1e-3) and boolean spellings read as numbers / booleans', async () => {
    const g = sheetOf((await L('hc-18-odd-lexical-values.xlsx')).book);
    const nums = [100, 0.5, 5, 12, 7, -0, 0.001].map((n, i) => [g.rows[i + 1]![2]!.v, n]);
    for (const [got, want] of nums) expect(got).toBeCloseTo(want as number, 12);
    expect(g.rows[1]![3]).toMatchObject({ t: 'b', v: true });
    expect(g.rows[4]![3]).toMatchObject({ t: 'b', v: true }); // <v>true</v>
  });
});

describe('nothing to do means nothing changes', () => {
  // replayLog with an empty log and buildPremerged with nothing to import must hand the workbook back as the reader saw it
  for (const f of files.filter((x) => !/hc-22|hc-24|hc-31|py-26/.test(x))) {
    it(`${f}: replayLog(file, []) reads back the same workbook`, async () => {
      const file = await L(f);
      const out = await readBook(await replayLog(file.bytes, []), f);
      expect(bookDiff(file.book, out)).toEqual([]);
    });
  }

  it('an external-workbook reference ([1]Sheet1!E2) does not follow the column moves of the local sheet that has the same name', async () => {
    const out = await replayLog(bytesOf('hc-37-external-link.xlsx'), [{ kind: 'struct', sheet: 'Sheet1', op: { type: 'move', axis: 'col', from: 5, count: 1, to: 1 } }]);
    const g = sheetOf(await readBook(out, 'x.xlsx'));
    expect(g.rows[1]![7]!.f).toBe('[1]Sheet1!E2+Sheet1!A2');
  });

  it('hc-36: theme-coloured cells of a source with another theme keep their resolved colours when imported', async () => {
    const src = await L('hc-36-theme2013-colours.xlsx');
    const hdr = src.book.styles[sheetOf(src.book).rows[0]![0]!.s ?? 0];
    const pm = await premergeFiles(await partner(), src);
    const g = sheetOf(pm.book);
    const col = g.rows[0]!.findIndex((c) => c?.v === '大学');
    expect(pm.book.styles[g.rows[0]![col]!.s ?? 0].fill).toBe(hdr.fill);
    expect(hdr.fill).toMatch(/^#[0-9A-F]{6}$/);
  });
});

describe('formulas without a stored result', () => {
  it('py-01 (openpyxl): the reader says how many formulas have no stored result; files with results (XlsxWriter, Google, Excel) say nothing', async () => {
    const warn = (b: SourceBook) => b.warnings.filter((w) => /計算結果が保存されていない/.test(w));
    expect(warn((await L('py-01-openpyxl-styled.xlsx')).book)).toHaveLength(1);
    expect(warn((await L('py-01-openpyxl-styled.xlsx')).book)[0]).toMatch(/32 個/); // 30 rows + the two 合計 formulas
    expect(warn((await L('py-01-openpyxl-styled.xlsx')).book)[0]).toMatch(/Excel で開いて保存し直す/);
    for (const name of ['py-15-xlsxwriter-basic.xlsx', 'hc-01-google-sheets.xlsx', 'hc-02-libreoffice.xlsx', 'hc-10-shared-formulas.xlsx', 'js-04-exceljs-basic.xlsx'])
      expect(warn((await L(name)).book), name).toEqual([]);
  });
});

describe('custom number formats with ids below 164', () => {
  it('js-10 (write-excel-file numbers its custom <numFmt>s from 100): an imported date keeps its format (it showed the serial 45416)', async () => {
    const src = await L('js-10-write-excel-file.xlsx');
    const g0 = sheetOf(src.book);
    const cell0 = g0.rows[3]![5]!; // 入学日 of S2024003
    expect(cell0.t).toBe('d');
    expect(cellText(src.book, cell0)).toBe('2024/05/04');
    const pm = await premergeFiles(await partner(), src);
    const g = sheetOf(pm.book);
    const col = g.rows[0]!.findIndex((c) => c?.v === '入学日');
    expect(cellText(pm.book, g.rows[1]![col])).toBe('2024/05/04');
    expect(pm.book.styles[g.rows[1]![col]!.s ?? 0].numFmt).toBe('yyyy/mm/dd');
  });
});

describe('empty number format codes', () => {
  it('js-12 (excel-export: <numFmt numFmtId="0" formatCode=""/>, x: prefixed parts, BOM): an empty code defines nothing, in the reader and in the patcher', async () => {
    const src = await L('js-12-excel-export.xlsx');
    expect(src.book.styles.some((s) => s.numFmt === '')).toBe(false);
    const pm = await premergeFiles(src, await partner());
    expect(pm.book.styles.some((s) => s.numFmt === '')).toBe(false);
    // an imported header keeps the style of the partner exactly (it showed numFmt "" before)
    const g = sheetOf(pm.book);
    const hdr = pm.book.styles[g.rows[0]![7]!.s ?? 0];
    expect(hdr.bold).toBe(true);
    expect(hdr.fill).toBe('#FFF2CC');
    expect(hdr).not.toHaveProperty('numFmt');
  });
});

describe('header cells that are dates or numbers', () => {
  it('a date header (shown 2024/04/01) is imported as its displayed text, not as the serial 45383', async () => {
    const z = await JSZip.loadAsync(bytesOf('py-01-openpyxl-styled.xlsx'));
    let sh = await z.file('xl/worksheets/sheet1.xml')!.async('string');
    const dateXf = /<c r="F2" s="(\d+)"/.exec(sh)![1];
    sh = sh.replace(/<c r="F1"[^>]*>.*?<\/c>/, `<c r="F1" s="${dateXf}"><v>45383</v></c>`).replace(/<c r="G1"[^>]*>.*?<\/c>/, '<c r="G1"><v>2024</v></c>');
    z.file('xl/worksheets/sheet1.xml', sh);
    const src = await loadBytes('numheader.xlsx', await z.generateAsync({ type: 'uint8array', compression: 'DEFLATE' }), 'f');
    expect(sheetOf(src.book).rows[0]!.map((c) => cellText(src.book, c))).toContain('2024/04/01');
    const pm = await premergeFiles(await partner(), src);
    const headers = sheetOf(pm.book).rows[0]!.map((c) => cellText(pm.book, c));
    expect(headers).toContain('2024/04/01');
    expect(headers).toContain('2024');
    expect(headers).not.toContain('45383');
    // and the same file as the BASE: its date header is what conflicts with an imported header of the same text
    const back = await premergeFiles(src, await partner());
    expect(sheetOf(back.book).rows[0]!.map((c) => cellText(back.book, c)).slice(0, 8)).toEqual(sheetOf(src.book).rows[0]!.map((c) => cellText(src.book, c)).slice(0, 8));
  });
});
